// 1. Buscamos el chat_id desde el nodo 'Datos a json' o directamente de los datos que entran
let chatId = "";
try {
  chatId = $('Datos a json').first().json.chat_id;
} catch (e) {
  chatId = $input.all()[0]?.json?.id_estudiante || "";
}

// 2. Inicializamos las variables para el mensaje y el almacenamiento indexado
let mensaje = "*📅 Detectamos que tienes las siguientes tutorías registradas:*\n\n";
let opcionesDisponibles = [];

// 3. Recorremos todas las tutorías que vienen de Google Sheets
for (const item of $input.all()) {
  const t = item.json;

  // Respaldo de seguridad para el chatId si no se encontró arriba
  if (!chatId && t.id_estudiante) {
    chatId = t.id_estudiante;
  }

  // 4. Formateamos el mensaje estético con su respectivo número de opción
  mensaje += `📚 *Materia:* ${t.materia}\n`;
  mensaje += `   📅 *Fecha:* ${t.fecha}  |  ⏰ *Hora:* ${t.hora}\n`;
  mensaje += `   🟢 *Status:* ${t.estado}\n\n`;

  // 5. Guardamos todas las coincidencias estructurales con el formato estandarizado
  opcionesDisponibles.push({
    id_tutoria: t.id_tutoria || "",
    id_tutor: t.id_tutor || "",
    materia: t.materia,
    fecha: t.fecha,
    hora: t.hora,
    estado: t.estado
  });

}
// 6. Construimos el objeto unificado con la acción específica de esta ruta
const estructuraFinal = {
  accion: "ver_tutorias",
  opciones: opcionesDisponibles
};

// 7. Lo transformamos en la cadena JSON limpia para tu Google Sheets
const datosParcialesString = JSON.stringify(estructuraFinal);

// Retornamos el formato estructurado idéntico al de tu primera rama
return [{
  json: {
    chat_id: chatId,
    texto_notificacion: mensaje.trim(),
    datos_parciales: datosParcialesString,
    total_items: $input.all().length
  }
}];

// 1. Obtenemos todos los elementos que entran al nodo
const itemsEntrada = $input.all();

// 🎯 FILTRADO Y ELIMINACIÓN DE DUPLICADOS CON SET
const combinacionesVistas = new Set();
const items = [];

itemsEntrada.forEach(item => {
  const t = item.json;
  if (!t) return;

  const estado = String(t.estado || "").trim().toLowerCase();

  // Evaluamos que el estado sea válido para cancelar
  if (estado === "por iniciar" || estado === "en progreso") {
    const idTutoria = String(t.id_tutoria || "").trim();
    const materiaStr = String(t.materia || "").trim().toLowerCase();

    // Llave única para el Set (Evita que el mismo registro clonado se liste dos veces)
    const llaveUnica = `${idTutoria}-${materiaStr}`;

    if (!combinacionesVistas.has(llaveUnica)) {
      combinacionesVistas.add(llaveUnica);
      items.push(item); // Guardamos el nodo completo en la lista limpia
    }
  }
});

let chatId = "";

// 2. Buscamos el chat_id desde el nodo 'Datos a json' o por defecto del primer ítem original
try {
  chatId = $('Datos a json').first().json.chat_id;
} catch (e) {
  chatId = itemsEntrada[0]?.json?.id_estudiante || items[0]?.json?.id_estudiante || "";
}

// Si no hay tutorías activas tras aplicar el filtro con Set, enviamos un texto controlado de error
if (items.length === 0) {
  return [{ 
    json: { 
      chat_id: chatId, 
      texto_notificacion: "❌ No se encontraron tutorías activas (Por iniciar / En progreso) para cancelar.",
      datos_parciales: JSON.stringify({ accion: "cancelar_tutoria", opciones: [] }),
      total_items: 0
    } 
  }];
}

// Aseguramos el chatId con el id_estudiante si venía vacío
if (!chatId && items[0].json.id_estudiante) {
  chatId = items[0].json.id_estudiante;
}

// 📌 FUNCIÓN AUXILIAR: Extrae los datos limpios de la fecha ISO sin alterar el día por zona horaria
function formatearFecha(fechaRaw) {
  if (!fechaRaw) return "N/A";
  try {
    const fStr = String(fechaRaw).trim();

    // Si viene en formato ISO largo (ej: 2026-07-10T16:09:22...), cortamos solo la parte de la fecha: "2026-07-10"
    if (fStr.includes('T')) {
      const fechaCorta = fStr.split('T')[0]; // Separa en la 'T' y se queda con "2026-07-10"
      return fechaCorta.replace(/-/g, '/');  // Convierte a "2026/07/10"
    }

    // Si ya era una fecha normal con guiones (2026-07-10), solo cambiamos los guiones por diagonales
    return fStr.replace(/-/g, '/');
  } catch (e) {
    return String(fechaRaw);
  }
}

// 3. Adaptamos el encabezado según la cantidad de tutorías activas únicas encontradas
let mensaje = "";
if (items.length === 1) {
  mensaje = "⚠️ *Detectamos que tienes la siguiente tutoría activa en curso:*\n\n";
} else {
  mensaje = "⚠️ *Detectamos que tienes las siguientes tutorías registradas:*\n\n";
}

let opcionesDisponibles = [];
let indiceMateria = 1;

// 4. Recorremos únicamente los elementos filtrados y limpios sin duplicados
for (const item of items) {
  const t = item.json;

  // Aplicamos el formato uniforme a la fecha
  const fechaFormateada = formatearFecha(t.fecha);

  // Formateamos el mensaje estético con su número correlativo limpio y la nueva estructura de fecha
  mensaje += `*${indiceMateria}.* 📚 *Materia:* ${t.materia}\n`;
  mensaje += `     📅 *Fecha:* ${fechaFormateada}  |  ⏰ *Hora:* ${t.hora}\n`;
  mensaje += `     🔴 *Status:* ${t.estado}\n\n`;

  // 5. Estructuramos el JSON con los datos exactos y formateados para persistencia
  opcionesDisponibles.push({
    opcion_numero: indiceMateria,
    id_tutoria: t.id_tutoria || "",
    id_tutor: t.id_tutor || "",
    materia: t.materia,
    fecha: fechaFormateada, // Se guarda homogeneizada como YYYY/MM/DD
    hora: t.hora,
    estado: t.estado
  });

  indiceMateria++;
}

mensaje += "───────────────────\n✏️ *Para cancelar una sesión, simplemente responde con el número correspondiente.*";

// 6. Construimos el objeto final con la acción de cancelar
const estructuraFinal = {
  accion: "cancelar_tutoria",
  opciones: opcionesDisponibles
};

// 7. Lo convertimos a string JSON listo para la celda de Google Sheets
const datosParcialesString = JSON.stringify(estructuraFinal);

// Retornamos el formato unificado para n8n
return [{
  json: {
    chat_id: chatId,
    texto_notificacion: mensaje.trim(),
    datos_parciales: datosParcialesString,
    total_items: items.length
  }
}];

const items = $input.all();
let chatId = "";

// 1. Buscamos el chat_id desde el nodo 'Datos a json' o del primer ítem como respaldo
try {
  chatId = $('Datos a json').first().json.chat_id;
} catch (e) {
  chatId = items[0]?.json?.id_estudiante || "";
}

// Si no hay nada en progreso, enviamos el texto controlado
if (items.length === 0) {
  return [{ 
    json: { 
      chat_id: chatId, 
      texto_notificacion: "❌ No se encontraron tutorías activas en curso para finalizar.",
      datos_parciales: JSON.stringify({ accion: "finalizar_tutoria", opciones: [] })
    } 
  }];
}

// Aseguramos el chatId si venía vacío desde el bloque try
if (!chatId && items[0].json.id_estudiante) {
  chatId = items[0].json.id_estudiante;
}

// 2. Adaptamos el encabezado según la cantidad de tutorías en progreso encontradas
let mensaje = "";
if (items.length === 1) {
  mensaje = "⚠️ *Detectamos la siguiente tutoría en curso activa:*\n\n";
} else {
  mensaje = "⚠️ *Detectamos que tienes las siguientes tutorías en curso registradas:*\n\n";
