    id_tutor: t.id_tutor || "",
    materia: t.materia,
    fecha: t.fecha,
    hora: t.hora,
    estado: t.estado
  });

  indiceMateria++;
}

mensaje += "───────────────────\n✏️ *Para dar por finalizada una sesión, simplemente responde con el número correspondiente.*";

// 5. Construimos el objeto unificado con la acción para cerrar la tutoría
const estructuraFinal = {
  accion: "finalizar_tutoria",
  opciones: opcionesDisponibles
};

// 6. Lo convertimos a string JSON plano para la celda de la hoja Sessions
const datosParcialesString = JSON.stringify(estructuraFinal);

// Retornamos el formato unificado para n8n
return [{
  json: {
    chat_id: chatId,
    texto_notificacion: mensaje.trim(),
    datos_parciales: datosParcialesString,
    total_items: items.length
  }
}];

// 1. Obtenemos los datos de ambos nodos de Google Sheets
const tutores = $('Select Tutores').all().map(item => item.json);
const disponibilidades = $('Select Materias').all().map(item => item.json);

// 2. Buscamos el chat_id del alumno desde el trigger inicial
let chatId = "";
try {
  chatId = $('registrar').first().json?.message?.chat?.id || "";
} catch (e) {
  chatId = $input.all()[0]?.json?.chat_id || "";
}

// 3. Inicializamos las variables para el mensaje y el almacenamiento
let mensaje = "📅 *Horarios y Tutores Disponibles:*\n\n";
let opcionesDisponibles = [];
let indiceMateria = 1;

// 4. Recorremos cada tutor para cruzarlo con sus disponibilidades
tutores.forEach(tutor => {
  const horasTutor = disponibilidades.filter(dispo => dispo.id_tutor === tutor.id_tutor);

  if (horasTutor.length > 0) {
    horasTutor.forEach(h => {
      // Formateamos el mensaje numérico para Telegram
      mensaje += `*${indiceMateria}.* 📚 *Materia:* ${tutor.especialidad_materias}\n`;
      mensaje += `   👨‍🏫 *Profesor:* ${tutor.nombre}\n`;
      mensaje += `   ⏳ *Horario:* ${h.dia_semana} de ${h.hora_inicio} a ${h.hora_fin}\n\n`;

      // 5. Guardamos TODAS las coincidencias con la estructura exacta que pediste
      opcionesDisponibles.push({
        opcion_numero: indiceMateria, // Te añado este índice para que sepas cuál eligió después
        id_tutor: tutor.id_tutor,
        nombre: tutor.nombre,
        materia: tutor.especialidad_materias,
        dia: h.dia_semana,
        hora_inicio: h.hora_inicio,
        hora_fin: h.hora_fin
      });

      indiceMateria++;
    });
  }
});

mensaje += "───────────────────\n✏️ *Para seleccionar una opción, simplemente responde con el número correspondiente.*";

// 6. Construimos el objeto final con la acción y la lista completa de opciones
const estructuraFinal = {
  accion: "crear_tutoria",
  opciones: opcionesDisponibles
};

// 7. Lo convertimos a string JSON listo para la celda de Google Sheets
const datosParcialesString = JSON.stringify(estructuraFinal);

// Retornamos el formato unificado para n8n
return [{
  json: {
    chat_id: chatId,
    texto_notificacion: mensaje.trim(),
    datos_parciales: datosParcialesString
  }
}];

// 1. Obtenemos la fila encontrada en el nodo 'Buscar por id1'
const filaGoogleSheets = $('Buscar por id1').first().json;

// 2. Extraemos y parseamos el objeto JSON de datos_parciales
const textoJson = filaGoogleSheets.datos_parciales;
if (!textoJson) {
  throw new Error("La columna 'datos_parciales' está vacía.");
}
const datosParciales = JSON.parse(textoJson);

// 3. Obtenemos el número de opción que el usuario escribió en Telegram
// (Asegúrate de cambiar 'Telegram Trigger' por el nombre exacto de tu disparador de entrada)
const respuestaUsuario = parseInt($('registrar').first().json?.message?.text?.trim());

if (isNaN(respuestaUsuario)) {
  throw new Error("La respuesta del usuario no es un número válido.");
}

// 4. Buscamos de forma exacta la opción que coincide con ese número
const opcionSeleccionada = datosParciales.opciones.find(o => parseInt(o.opcion_numero) === respuestaUsuario);

// Si el usuario puso un número que no estaba en la lista
if (!opcionSeleccionada) {
  return [{
    json: {
      error: true,
      mensaje: "⚠️ Opción no válida. Por favor, selecciona un número de la lista."
    }
  }];
}

// 5. Retornamos ÚNICAMENTE los datos de la materia/tutoría seleccionada junto con la acción original
return [{
  json: {
    error: false,
    accion: datosParciales.accion, // Te servirá para el Router/Switch (ej: "crear_tutoria")
    ...opcionSeleccionada          // Esto saca id_tutor, nombre, materia, dia, hora_inicio, etc., limpios al primer nivel
  }
}];

// 1. Obtenemos la sesión del alumno desde el nodo 'Buscar por id2'
const filaSesion = $('Buscar por id2').first().json;
const textoJson = filaSesion.datos_parciales;
if (!textoJson) {
  throw new Error("La columna 'datos_parciales' está vacía.");
}
const datosParciales = JSON.parse(textoJson);

// 2. Obtenemos TODAS las filas obtenidas desde tu nodo de Google Sheets para el ID secuencial
let filasTutorias = [];
try {
  filasTutorias = $('BUscar id tutoria').all();
} catch (e) {
  filasTutorias = [];
}

// 3. Recorremos los registros globales para calcular el ID numérico más alto
let maxIdNumerico = 0;
filasTutorias.forEach(item => {
  const tutoria = item.json;
  // Nos aseguramos de que id_tutoria exista y sea un texto válido antes de procesar
  if (tutoria && tutoria.id_tutoria && typeof tutoria.id_tutoria === 'string' && tutoria.id_tutoria.trim() !== "") {
    const numeroExtraido = parseInt(tutoria.id_tutoria.replace(/[^0-9]/g, ''), 10);
    if (!isNaN(numeroExtraido) && numeroExtraido > maxIdNumerico) {
      maxIdNumerico = numeroExtraido;
    }
  }
});

const nuevoNumero = maxIdNumerico + 1;
const nuevoIdTutoria = "TUTOR" + String(nuevoNumero).padStart(3, '0');

// 4. Extraemos el nombre del Profesor o Materia del mensaje
let opcionSeleccionada = null;
try {
  const mensajeTelegram = $('Confirmar').first().json?.callback_query?.message?.text || "";

  if (Array.isArray(datosParciales.opciones)) {
    opcionSeleccionada = datosParciales.opciones.find(o => {
      return mensajeTelegram.includes(o.nombre) || mensajeTelegram.includes(o.materia);
    });
  }
} catch (e) {
  opcionSeleccionada = null;
}

// Si por alguna razón de formato no lo encuentra, tomamos el primero como respaldo
if (!opcionSeleccionada) {
  opcionSeleccionada = Array.isArray(datosParciales.opciones) ? datosParciales.opciones[0] : datosParciales.opciones;
}

if (!opcionSeleccionada) {
  return [{
    json: { error: true, mensaje: "⚠️ No hay ninguna tutoría pendiente para confirmar." }
  }];
}

// 6. Retornamos el objeto unificado limpio con los datos del profesor correcto
return [{
  json: {
    error: false,
    accion: datosParciales.accion,
    id_tutoria_nuevo: nuevoIdTutoria,
    ...opcionSeleccionada
  }
  }];

