// 1. Obtenemos los datos parciales de la sesión guardada (desde el nodo 'Buscar id1')
const datosSesion = $('Buscar id1').first().json;
const textoJson = datosSesion.datos_parciales;

if (!textoJson) {
  throw new Error("No se encontraron datos parciales en la sesión actual.");
}
const datosParciales = JSON.parse(textoJson);

// 2. Extraemos el callback data para validar la acción desde el nodo 'Confirmar2'
const callbackData = $('Confirmar2').first().json?.callback_query?.data || "";

// 3. Buscaremos la opción activa que guardamos en 'datos_parciales'.
let tutoríaElegida = null;

if (Array.isArray(datosParciales.opciones) && datosParciales.opciones.length > 0) {
  // Si quedan opciones en el arreglo, tomamos la primera en cola para el flujo
  tutoríaElegida = datosParciales.opciones[0]; 
} else if (datosParciales.id_tutoria_a_finalizar) {
  // O si guardaste directamente el ID en la raíz del JSON en la pantalla anterior
  tutoríaElegida = datosParciales;
}

// Validamos el ID dinámicamente buscando tanto bajo la estructura de finalizar como la de respaldos previos
const idBuscar = tutoríaElegida?.id_tutoria || datosParciales.id_tutoria_a_finalizar || datosParciales.id_tutoria_a_cancelar;

if (!idBuscar) {
  throw new Error("No se pudo determinar cuál tutoría se iba a marcar como finalizada desde los datos de la sesión.");
}

// 4. Obtenemos todas las filas de tutorías traídas por el nodo 'Tutorias1'
const filasTutoriasRaw = $('Tutorias1').all();

// 5. Buscamos la fila exacta dentro de las filas de la hoja usando el id_tutoria
const filaEnHoja = filasTutoriasRaw.find(item => {
  return String(item.json?.id_tutoria).trim() === String(idBuscar).trim();
});

if (!filaEnHoja) {
  throw new Error(`No se encontró ningún registro en la hoja de cálculo con el ID: ${idBuscar}`);
}

// 6. Retornamos los datos limpios y listos para el nodo de Google Sheets (Update Row)
return [{
  json: {
    // Fila exacta en Google Sheets que se va a modificar
    row_number: filaEnHoja.json.row_number, 
    id_tutoria_a_finalizar: idBuscar,

    // Datos para el mensaje de Telegram subsiguiente
    chat_id: datosSesion.telegram_id,
    materia: filaEnHoja.json.materia || tutoríaElegida?.materia || "",
    fecha: filaEnHoja.json.fecha || tutoríaElegida?.fecha || "",
    hora: filaEnHoja.json.hora || tutoríaElegida?.hora || "",

    // 🎯 NUEVO ESTADO: Cambiado a Finalizada para inyectar directamente en el Update
    nuevo_estado: "Finalizada"
  }
}];
